{
    // Same DbContext instance as the handler if both resolved in same request
    public Task<Order?> GetAsync(Guid id) => db.Orders.FindAsync(id).AsTask();
}

public sealed class OutboxDispatcher(IServiceScopeFactory scopeFactory) : BackgroundService
{
    protected override async Task ExecuteAsync(CancellationToken stoppingToken)
    {
        while (!stoppingToken.IsCancellationRequested)
        {
            await using var scope = scopeFactory.CreateAsyncScope();
            var db = scope.ServiceProvider.GetRequiredService<AppDbContext>();

            var batch = await db.OutboxMessages
                .Where(m => m.ProcessedAt == null)
                .Take(20)
                .ToListAsync(stoppingToken);

            // process batch...
            await db.SaveChangesAsync(stoppingToken);
        }
    }
}

// WRONG: parallel operations on one DbContext
var orders = await db.Orders.ToListAsync(ct);
await Parallel.ForEachAsync(orders, ct, async (order, token) =>
{
    order.Processed = true;
    await db.SaveChangesAsync(token); // InvalidOperationException under load
});

// CORRECT: sequential SaveChanges once, or separate scope per parallel unit
foreach (var order in orders) order.Processed = true;
await db.SaveChangesAsync(ct);

