// Integration test: two parallel requests get different context instances
[Fact]
public async Task Parallel_requests_use_separate_dbcontexts()
{
    var factory = new WebApplicationFactory<Program>();
    var client = factory.CreateClient();
    var t1 = client.GetAsync("/api/orders");
    var t2 = client.GetAsync("/api/orders");
    await Task.WhenAll(t1, t2);
    // Under captive dependency, ActiveDbContexts stays at 1 during load test
}
